# Sentences that lean on an earlier one (deps) and the sentences each written question needs (written[k] -> idx).
def _annotate(theme, deps, needs):
    theme['deps'] = deps
    theme['written'] = [w + (tuple(needs.get(k, ())),) for k, w in enumerate(theme['written'])]


